import{_ as a}from"./chunks/02.CDe4raOw.js";import{_ as n,o as r,c as d,aa as o,j as e}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/cs/diary/kopirovani_zaznamu.png",i="/buildary-help-preview/media/cs/diary/kopirovani_od_subdodavatelu.png",y=JSON.parse('{"title":"Kopírovat záznamy","description":"","frontmatter":{"title":"Kopírovat záznamy","wiki":"cs:diary:copydailyentries"},"headers":[],"relativePath":"diary/copydailyentries.md","filePath":"diary/copydailyentries.md","lastUpdated":1794209661000}'),p={name:"diary/copydailyentries.md"};function l(v,t,z,k,c,u){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="kopirovat-zaznamy" tabindex="-1">Kopírovat záznamy <a class="header-anchor" href="#kopirovat-zaznamy" aria-label="Permalink to &quot;Kopírovat záznamy&quot;">​</a></h1><p>Po sobě jdoucí dny na stavbě bývají podobné. Záznamy proto nemusíte psát znovu: převezměte je z jiného dne, z deníků podzhotovitelů nebo z deníků částí stavby a upravte jen to, co se změnilo.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/kopirovani">Zkopírovat zápisy z předchozího dne nebo od podzhotovitele</a> v Akademii.</p><h2 id="odkud-lze-kopirovat" tabindex="-1">Odkud lze kopírovat <a class="header-anchor" href="#odkud-lze-kopirovat" aria-label="Permalink to &quot;Odkud lze kopírovat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Odkud</th><th>Kde to najdete</th><th>Co se převezme</th></tr></thead><tbody><tr><td>Jiný den tohoto deníku – jedna sekce</td><td>Tlačítko <strong>Kopírovat záznamy</strong> v sekci</td><td>Záznamy vybrané sekce.</td></tr><tr><td>Jiný den tohoto deníku – celý den</td><td><strong>Další volby</strong> → <strong>Kopíruj den</strong></td><td>Záznamy ze sekcí, které zaškrtnete.</td></tr><tr><td>Deníky podzhotovitelů</td><td><strong>Další volby</strong> → <strong>Kopíruj z propojených deníků</strong></td><td>Vybrané záznamy z deníků podzhotovitelů.</td></tr><tr><td>Deníky částí stavby</td><td><strong>Další volby</strong> → <strong>Kopíruj z deníků částí staveb</strong></td><td>Jen provedené práce.</td></tr></tbody></table><p>Záznamy se vždy kopírují do dne, který máte otevřený.</p><figure class="shot" style="--w:760px;"><img src="'+a+'" alt="Menu Další volby dne s volbami Kopíruj den, Kopíruj z propojených deníků a Kopíruj z deníků částí staveb" loading="lazy"></figure><h2 id="kopirovat-z-jineho-dne" tabindex="-1">Kopírovat z jiného dne <a class="header-anchor" href="#kopirovat-z-jineho-dne" aria-label="Permalink to &quot;Kopírovat z jiného dne&quot;">​</a></h2>',8),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/PBWKQYCG4I8",title:"Video: Kopírování záznamů z jiných dnů",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),o('<p>Jednu sekci zkopírujete tlačítkem <strong>Kopírovat záznamy</strong>, které je v sekci vedle <strong>Přidat záznam</strong>. Celý den zkopírujete v <strong>Dalších volbách</strong> volbou <strong>Kopíruj den</strong>.</p><p>V okně kopírování nastavíte:</p><ul><li><strong>Den, ze kterého se budou kopírovat data</strong> – vyberete ho v kalendáři. Kalendář ukazuje stav dnů stejnými barvami a ikonami jako kalendářní lišta.</li><li><strong>Sekce</strong> – zaškrtněte sekce, ze kterých se mají záznamy převzít.</li><li><strong>Kopírovat s přílohami</strong> – zda se zkopírují i přílohy záznamů.</li><li><strong>Záznamy dle autora</strong> – <strong>Všichni</strong>, <strong>Mé záznamy</strong>, nebo <strong>Záznamy mé firmy</strong>.</li></ul><p>Kopírování dokončíte tlačítkem <strong>Kopíruj</strong>.</p><figure class="shot" style="--w:640px;"><img src="'+s+'" alt="Okno kopírování s kalendářem, výběrem sekcí, volbou příloh a výběrem autorů" loading="lazy"></figure><div class="info custom-block"><p class="custom-block-title">Počasí se nekopíruje</p><p>Počasí se z jiného dne nikdy nepřebírá. Pro otevřený den se vždy znovu načte ze serveru.</p></div><h2 id="kopirovat-z-deniku-podzhotovitelu" tabindex="-1">Kopírovat z deníků podzhotovitelů <a class="header-anchor" href="#kopirovat-z-deniku-podzhotovitelu" aria-label="Permalink to &quot;Kopírovat z deníků podzhotovitelů&quot;">​</a></h2>',7),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/IbyZ6Av8g7s",title:"Video: Kopírování záznamů z deníků podzhotovitelů",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),o('<p>Pokud mají významní podzhotovitelé na stavbě vlastní deníky v Buildary, převezmete jejich záznamy do svého deníku vedeného vůči stavebníkovi. Ušetříte tím přepisování a zároveň nejrychleji zkontrolujete, co podzhotovitelé ten den zapsali.</p><p>Deník podzhotovitele musí být s vaším deníkem propojený: v jeho nastavení je váš deník uvedený jako <strong>Nadřazený deník</strong> – viz <a href="/buildary-help-preview/diary/diarysetup">Založit deník</a>.</p><p>V <strong>Dalších volbách</strong> zvolte <strong>Kopíruj z propojených deníků</strong>. Okno se seznamem deníků podzhotovitelů ukáže všechny propojené deníky, které v daném dni obsahují záznamy. Deník bez záznamů v seznamu není.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Okno se seznamem deníků podzhotovitelů a jejich záznamů rozdělených po sekcích" loading="lazy"></figure><ul><li>Deníky rozbalíte až na jednotlivé záznamy. Zaškrtnutím vyberete celý deník, sekci nebo jednotlivý záznam.</li><li>Text záznamů můžete před zkopírováním upravit. Původní záznam v deníku podzhotovitele se nezmění.</li><li>Kopírovat lze i přílohy.</li></ul><p>Tlačítkem <strong>Kopíruj</strong> se vybrané záznamy přenesou do vašeho deníku.</p><h2 id="kopirovat-z-deniku-casti-stavby" tabindex="-1">Kopírovat z deníků částí stavby <a class="header-anchor" href="#kopirovat-z-deniku-casti-stavby" aria-label="Permalink to &quot;Kopírovat z deníků částí stavby&quot;">​</a></h2><p>Pokud je stavba rozdělená na objekty nebo provozní celky a každý z nich má vlastní deník (deník části stavby), můžete jejich záznamy převzít do centrálního deníku stavby. Z deníků částí stavby se přebírají jen záznamy ze sekce <strong>Provedené práce</strong>.</p><p>V <strong>Dalších volbách</strong> zvolte <strong>Kopíruj z deníků částí staveb</strong>, zaškrtněte záznamy a zkopírujte je.</p><p>Všechny převzaté práce z jednoho deníku části stavby se vloží do jednoho záznamu centrálního deníku. Záznam je nadepsaný číslem a názvem deníku části stavby, jednotlivé práce jsou v něm pod sebou.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>První záznam každého deníku části stavby je k převzetí předem zaškrtnutý. Formulujte ho proto tak, aby se dal rovnou převzít do centrálního deníku.</p></div><p>Jak stavbu rozdělit na části, popisují <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</p>',12)])])}const b=n(p,[["render",l]]);export{y as __pageData,b as default};
